  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

    /* ── Renderer ────────────────────────────────────────────────────────── */
    const canvas = document.getElementById('c');
    const _stage = document.getElementById('stage');
    const _ui = document.getElementById('ui');
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });

    /* ── UI layout: dock heavy controls instead of covering the figure ───────
     * setUiLayout('overlay' | 'right' | 'bottom', sizePx?)
     *   overlay — #ui floats bottom-left over the figure. Not used by the
     *             auto-dock heuristic below; available only as an explicit override.
     *   right   — #ui becomes a real column; the figure shrinks to fit beside it.
     *             The auto-dock default.
     *   bottom  — same, as a strip under the figure. The auto-dock default on
     *             narrow viewports (<560px).
     * The stage's ResizeObserver re-fits the camera afterwards, so docking
     * re-frames the figure rather than cropping it. Calling this explicitly also
     * turns OFF the auto-dock heuristic below.
     */
    let _uiLayoutExplicit = false;

    function setUiLayout(mode = 'overlay', sizePx) {
      _uiLayoutExplicit = true;
      _applyUiLayout(mode, sizePx);
    }

    function _applyUiLayout(mode, sizePx) {
      const next = (mode === 'right' || mode === 'bottom') ? mode : 'overlay';
      if (next === 'overlay') document.body.removeAttribute('data-ui-layout');
      else document.body.setAttribute('data-ui-layout', next);
      if (sizePx) document.body.style.setProperty('--ui-size', `${sizePx}px`);
    }

    // Auto-dock: generated figures do not reliably remember to call
    // setUiLayout, and an overlay that covers the figure is the single most
    // common way these demos fail. So always dock #ui to a side column instead
    // of floating it over the figure. Deciding this from content height alone
    // caused a visible mid-session layout jump on demos whose content grows
    // between interactive states (e.g. demo_steps with longer/shorter
    // narration per step) — always docking avoids that entirely.
    function _autoUiLayout() {
      if (_uiLayoutExplicit) return;
      const hasEditor = Boolean(_ui.querySelector('textarea'));
      const narrow = window.innerWidth < 560;
      const mode = narrow ? 'bottom' : 'right';
      const start = narrow ? (hasEditor ? 300 : 220) : (hasEditor ? 400 : 300);
      _applyUiLayout(mode, start);
      _growDockToFit(mode, start);
    }

    // A fixed dock size still clips a long control stack in a small inline
    // figure. Grow the dock until the panel stops scrolling, capped so the
    // figure always keeps the larger share of the frame.
    function _growDockToFit(mode, startPx) {
      const cap = mode === 'bottom'
        ? Math.round(window.innerHeight * 0.5)
        : Math.round(window.innerWidth * 0.45);
      // Clamp down too: on a small figure the default dock can itself exceed the
      // cap, and the figure must always keep the larger share.
      let size = Math.min(startPx, cap);
      if (size !== startPx) document.body.style.setProperty('--ui-size', `${size}px`);
      let guard = 0;
      const step = () => {
        if (_uiLayoutExplicit || guard++ > 6) return;
        if (_ui.scrollHeight <= _ui.clientHeight + 2 || size >= cap) return;
        size = Math.min(cap, size + 60);
        document.body.style.setProperty('--ui-size', `${size}px`);
        requestAnimationFrame(step);
      };
