  const p2 = projectFromCameraToPlane(C2, P, plane2Center, n2);
  const p1OnPlane2 = projectFromCameraToPlane(C2, p1, plane2Center, n2);
  const [lineA, lineB] = clipLineToPlaneRect(e2, p2, plane2Center, plane2.u, plane2.v, plane2.width, plane2.height);

  addDashedSegment(dynamicGroup, C1, C2, BLACK, 0.018, 0.26, 0.18);
  addDashedSegment(dynamicGroup, C2, P, BLACK, 0.018, 0.25, 0.17);
  addDashedSegment(dynamicGroup, C1, e2, BLACK, 0.016, 0.23, 0.17);
  addDashedSegment(dynamicGroup, P, p2, BLACK, 0.016, 0.23, 0.16);
  addDashedSegment(dynamicGroup, p1, p1OnPlane2, BLACK, 0.016, 0.23, 0.16);

  addCylinderBetween(dynamicGroup, lineA, lineB, 0.048, RED, 1, 24);

  const epipolarPlaneGeom = new THREE.BufferGeometry().setFromPoints([C1, C2, P]);
  epipolarPlaneGeom.setIndex([0, 1, 2]);
  const epipolarPlane = new THREE.Mesh(
    epipolarPlaneGeom,
    new THREE.MeshBasicMaterial({
      color: MAGENTA,
      transparent: true,
      opacity: 0.10,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  dynamicGroup.add(epipolarPlane);

  addPoint(dynamicGroup, e2, RED, 0.112);
  addPoint(dynamicGroup, p2, GREEN, 0.112);
  addPoint(dynamicGroup, p1OnPlane2, CYAN, 0.098);

  const origin2 = plane2Center.clone().addScaledVector(n2, 0.10);
  const x2Tip = addArrow(dynamicGroup, origin2, plane2.u.clone().multiplyScalar(-1), 1.12, BLUE, 0.019, 0.92);
  const y2Tip = addArrow(dynamicGroup, origin2, plane2.v, 1.16, BLUE, 0.019, 0.92);
  const z2Tip = addArrow(dynamicGroup, origin2, n2, 0.94, BLUE, 0.019, 0.92);

  const tStart = C1.clone().add(new THREE.Vector3(0.05, -0.58, 0.62));
  const tEnd = C2.clone().add(new THREE.Vector3(-0.05, -0.58, 0.62));
  addArrow(dynamicGroup, tStart, new THREE.Vector3().subVectors(tEnd, tStart), tStart.distanceTo(tEnd), GREEN, 0.026, 1.08);

  const curveStart = C1.clone().add(new THREE.Vector3(1.05, -1.05, 0.92));
  const curveEnd = C2.clone().add(new THREE.Vector3(-1.10, -1.05, 0.92));
  const curveControl = new THREE.Vector3((curveStart.x + curveEnd.x) * 0.5, -3.42, 1.22);
  addCurvedArrow(dynamicGroup, curveStart, curveControl, curveEnd, GREEN, 0.032);

  labels.camera2.pos.copy(C2).add(new THREE.Vector3(0.76, -0.45, -0.02));
  labels.image2.pos.copy(plane2.corners[2]).add(new THREE.Vector3(0.06, 0.23, 0.02));
  labels.p2.pos.copy(p2).add(new THREE.Vector3(-0.33, 0.02, 0.04));
  labels.epipolar.pos.copy(lineA).lerp(lineB, 0.72).add(new THREE.Vector3(0.04, 0.19, 0.04));
  labels.rayProjection.pos.copy(lineA).lerp(lineB, 0.42).add(new THREE.Vector3(0.09, -0.16, 0.04));
  labels.e2.pos.copy(e2).add(new THREE.Vector3(0.20, -0.16, 0.02));
  labels.p1to2.pos.copy(p1OnPlane2).add(new THREE.Vector3(0.20, 0.15, 0.02));
  labels.pointP2.pos.copy(p2).add(new THREE.Vector3(0.18, 0.18, 0.02));
  labels.x2.pos.copy(x2Tip);
  labels.y2.pos.copy(y2Tip);
  labels.z2.pos.copy(z2Tip);
  labels.axes2.pos.copy(origin2).add(new THREE.Vector3(0.54, 0.16, 0.02));
  labels.T.pos.copy(tStart).lerp(tEnd, 0.5).add(new THREE.Vector3(0, 0.22, 0.02));
  labels.RT.pos.copy(curveControl).add(new THREE.Vector3(0, -0.20, 0));

  document.getElementById('rotationCamera2Value').textContent = `${Math.round(state.rotationCamera2)}\u00b0`;
  document.getElementById('translationCamera2Value').textContent = state.translationCamera2.toFixed(1);
  document.getElementById('rotationCamera2').value = state.rotationCamera2;
  document.getElementById('translationCamera2').value = state.translationCamera2;

  for (let i = 0; i < 3; i++) {
    document.getElementById(`step${i}`).classList.toggle('active', state.activeStep === i);
  }
  const step = demoSteps[state.activeStep];
  document.getElementById('stepNarration').textContent = step ? step.narration : 'Adjust either slider independently to explore how camera pose changes the epipolar constraint.';
}

const rotationInput = document.getElementById('rotationCamera2');
const translationInput = document.getElementById('translationCamera2');

rotationInput.addEventListener('input', () => {
  state.tween = null;
  state.activeStep = -1;
  state.rotationCamera2 = Number(rotationInput.value);
  updateScene();
});

translationInput.addEventListener('input', () => {
  state.tween = null;
  state.activeStep = -1;
  state.translationCamera2 = Number(translationInput.value);
  updateScene();
});

function goToStep(i) {
  const target = demoSteps[i];
  if (!target) return;

  state.activeStep = i;
  state.tween = {
    startTime: performance.now(),
    duration: 1000,
    fromRotation: state.rotationCamera2,
    fromTranslation: state.translationCamera2,
    toRotation: target.rotationCamera2,
    toTranslation: target.translationCamera2
  };

  function tick(now) {
    if (!state.tween) return;
    const t = Math.min((now - state.tween.startTime) / state.tween.duration, 1);
    const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    state.rotationCamera2 = THREE.MathUtils.lerp(state.tween.fromRotation, state.tween.toRotation, eased);
    state.translationCamera2 = THREE.MathUtils.lerp(state.tween.fromTranslation, state.tween.toTranslation, eased);
    updateScene();

    if (t < 1) {
      requestAnimationFrame(tick);
    } else {
      state.rotationCamera2 = state.tween.toRotation;
      state.translationCamera2 = state.tween.toTranslation;
      state.tween = null;
      updateScene();
    }
  }

  requestAnimationFrame(tick);
}

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
window.goToStep = goToStep;

camera.position.set(0.38, 3.05, 9.65);
controls.target.set(0.02, -0.44, 0.24);
camera.zoom = 0.52;
camera.lookAt(controls.target);
camera.updateProjectionMatrix();
controls.update();
HOME_POS.copy(camera.position);
HOME_TARGET.copy(controls.target);
HOME_ZOOM = camera.zoom;

updateScene();
// @FIGURE_CODE_END

