<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// rounded-corner legend box → addLabel HTML rounded div with two arrow rows
// legend black right-pointing arrow → HTML arrow glyph inside legend
// legend pale blue right-pointing arrow → HTML arrow glyph inside legend
// noisy input/output feature planes → PlaneGeometry + DataTexture speckle + black Line outline
// feature map residual volumes → BoxGeometry cuboids with MeshBasicMaterial face colors + EdgesGeometry outlines
// self-attention-capable volumes → same cuboids registered interactive with pale-blue highlight tint
// flow arrows → THREE.Line segments + ConeGeometry arrowheads
// skip connections → salmon THREE.Line polylines + ConeGeometry arrowheads
// timestep node → CircleGeometry disk + RingGeometry outline + addLabel "t"
// time embedding baseline and injection arrows → blue-gray Lines + ConeGeometry arrowheads
// sinusoidal embedding strip → row of small PlaneGeometry tiles recolored by timestep
// self-attention overlay → Group with panel PlaneGeometry, 16×16 cell planes, attention rays, and plain residual mini-diagram boxes

const COLORS = {
  front: 0x7f3d22,
  side: 0xcf7d59,
  skip: 0xd57d5c,
  time: 0x4f6f80,
  attn: 0x9fc3d5,
  label: '#854126',
  active: 0xffd34d,
  black: 0x000000
};

const root = new THREE.Group();
scene.add(root);

const blockRecords = [];
const blockByPhase = new Map();
const skipRecords = [];
let currentPhase = 'input';
let currentStep = 0;
let overlayOpen = false;

function makeLine(points, color = 0x000000, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const line = new THREE.Line(geom, mat);
  root.add(line);
  return line;
}

function makeArrow(points, color = 0x000000, size = 0.09, opacity = 1, parent = root) {
  const group = new THREE.Group();
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const line = new THREE.Line(geom, mat);
  group.add(line);

  const a = points[points.length - 2];
  const b = points[points.length - 1];
  const dir = new THREE.Vector3().subVectors(b, a).normalize();
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(size, size * 2.25, 18),
    new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity })
  );
  cone.position.copy(b);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.add(cone);
  parent.add(group);
  return group;
}

function setObjectOpacity(obj, opacity) {
  obj.traverse(o => {
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach(m => {
        m.transparent = opacity < 1;
        m.opacity = opacity;
        m.needsUpdate = true;
      });
    }
  });
}

function makeBoxVolume({ id, phase, x, h, w, depth, attention = false }) {
  const group = new THREE.Group();
  const yBase = -1.45;
  group.position.set(x, yBase + h / 2, -depth / 2);

  const sideMat = new THREE.MeshBasicMaterial({ color: attention ? 0xd58a67 : COLORS.side, transparent: true, opacity: 1 });
  const topMat = new THREE.MeshBasicMaterial({ color: 0xd98a64, transparent: true, opacity: 1 });
  const frontMat = new THREE.MeshBasicMaterial({ color: COLORS.front, transparent: true, opacity: 1 });
  const mats = [sideMat, sideMat, topMat, sideMat, frontMat, sideMat];

  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, depth), mats);
  group.add(mesh);

  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  group.add(edges);

  const activeEdges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry),
    new THREE.LineBasicMaterial({ color: COLORS.active })
  );
  activeEdges.scale.set(1.08, 1.04, 1.08);
  activeEdges.visible = false;
  group.add(activeEdges);

  root.add(group);

  const record = { id, phase, group, mesh, edges, activeEdges, x, h, w, depth, yBase, attention };
  blockRecords.push(record);
  if (phase) blockByPhase.set(phase, record);

  if (attention) {
    registerInteractive(group, {
      title: 'Self-attention residual block',
      tooltip: 'Click to expand 16×16 self-attention',
      body: 'At 16×16, each token can mix information from all 256 spatial positions rather than only nearby convolutional neighborhoods.',
      onClick: () => toggleAttentionOverlay(true)
    });
  }

  return record;
}

function noisyTexture(seedOffset = 0) {
  const W = 72, H = 72;
  const data = new Uint8Array(W * H * 4);
  let s = 123456 + seedOffset;
  function rand() {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  }
  for (let i = 0; i < W * H; i++) {
    const base = 120 + Math.floor(rand() * 90);
    data[i * 4 + 0] = Math.max(0, Math.min(255, base + (rand() - 0.5) * 70));
    data[i * 4 + 1] = Math.max(0, Math.min(255, base + (rand() - 0.5) * 65));
    data[i * 4 + 2] = Math.max(0, Math.min(255, base + (rand() - 0.5) * 85));
    data[i * 4 + 3] = 255;
  }
  const tex = new THREE.DataTexture(data, W, H, THREE.RGBAFormat);
  tex.needsUpdate = true;
  return tex;
}

function makePlaneFeature(id, x, output = false) {
  const h = 3.6, w = 0.86, yBase = -1.45;
  const group = new THREE.Group();
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({ map: noisyTexture(output ? 99 : 0), side: THREE.DoubleSide })
  );
  mesh.position.set(x, yBase + h / 2, 0.025);
  group.add(mesh);

  const pts = [
    new THREE.Vector3(x - w / 2, yBase, 0.035),
    new THREE.Vector3(x + w / 2, yBase, 0.035),
    new THREE.Vector3(x + w / 2, yBase + h, 0.035),
    new THREE.Vector3(x - w / 2, yBase + h, 0.035),
    new THREE.Vector3(x - w / 2, yBase, 0.035)
  ];
  const outline = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  group.add(outline);

  const activeEdges = outline.clone();
  activeEdges.material = new THREE.LineBasicMaterial({ color: COLORS.active });
  activeEdges.visible = false;
  group.add(activeEdges);

  root.add(group);
  const record = { id, phase: output ? 'output' : 'input', group, mesh, activeEdges, x, h, w, depth: 0.05, yBase };
  blockRecords.push(record);
  blockByPhase.set(record.phase, record);
  return record;
}

const inputPlane = makePlaneFeature('input-plane', -7.05, false);
const enc256a = makeBoxVolume({ id: 'enc256a', phase: 'encoder256', x: -6.45, h: 3.6, w: 0.25, depth: 0.55 });
const enc256b = makeBoxVolume({ id: 'enc256b', phase: null, x: -5.96, h: 3.6, w: 0.34, depth: 0.68 });
const enc128 = makeBoxVolume({ id: 'enc128', phase: 'encoder128', x: -5.18, h: 1.8, w: 0.42, depth: 0.63 });
const enc64 = makeBoxVolume({ id: 'enc64', phase: 'encoder64', x: -4.32, h: 0.9, w: 0.48, depth: 0.54 });
const enc32 = makeBoxVolume({ id: 'enc32', phase: 'encoder32', x: -3.34, h: 0.48, w: 1.00, depth: 0.36 });
const enc16 = makeBoxVolume({ id: 'enc16', phase: 'encoder16', x: -2.04, h: 0.25, w: 1.10, depth: 0.30, attention: true });
const bottleneck = makeBoxVolume({ id: 'bottleneck', phase: 'bottleneck8', x: -0.82, h: 0.18, w: 0.88, depth: 0.24, attention: true });
const dec8 = makeBoxVolume({ id: 'dec8', phase: null, x: 0.52, h: 0.18, w: 0.88, depth: 0.24 });
const dec16 = makeBoxVolume({ id: 'dec16', phase: 'decoder16', x: 1.84, h: 0.25, w: 1.02, depth: 0.30, attention: true });
const dec32 = makeBoxVolume({ id: 'dec32', phase: 'decoder32', x: 3.02, h: 0.48, w: 0.72, depth: 0.38 });
const dec64 = makeBoxVolume({ id: 'dec64', phase: 'decoder64', x: 3.95, h: 0.9, w: 0.50, depth: 0.56 });
const dec128 = makeBoxVolume({ id: 'dec128', phase: 'decoder128', x: 4.60, h: 1.8, w: 0.40, depth: 0.64 });
const dec256 = makeBoxVolume({ id: 'dec256', phase: 'decoder256', x: 5.34, h: 3.6, w: 0.34, depth: 0.68 });
const outBlock = makeBoxVolume({ id: 'outBlock', phase: null, x: 5.78, h: 3.6, w: 0.25, depth: 0.55 });
const outputPlane = makePlaneFeature('output-plane', 6.48, true);

const pathRecords = [inputPlane, enc256a, enc256b, enc128, enc64, enc32, enc16, bottleneck, dec8, dec16, dec32, dec64, dec128, dec256, outBlock, outputPlane];

for (let i = 0; i < pathRecords.length - 1; i++) {
  const a = pathRecords[i], b = pathRecords[i + 1];
  const y = -1.47;
  makeArrow([
    new THREE.Vector3(a.x + (a.w || 0.2) / 2 + 0.05, y, 0.06),
    new THREE.Vector3(b.x - (b.w || 0.2) / 2 - 0.05, y, 0.06)
  ], 0x222222, 0.055, 0.85);
}

function topOf(r, extra = 0) {
  return new THREE.Vector3(r.x, r.yBase + r.h + extra, 0.1);
}

function makeSkip(name, from, to, yTop, label, labelX) {
  const start = topOf(from, 0.32);
  const end = topOf(to, 0.32);
  const pts = [
    new THREE.Vector3(start.x + 0.18, start.y, 0.15),
    new THREE.Vector3(start.x + 1.00, yTop, 0.15),
    new THREE.Vector3(to.x - 1.00, yTop, 0.15),
    new THREE.Vector3(end.x - 0.18, end.y, 0.15)
  ];
  const arrow = makeArrow(pts, COLORS.skip, 0.085, 0.95);
  skipRecords.push({ name, arrow, phase: name });
  if (label) addLabel('Concatenate', new THREE.Vector3(labelX, yTop + 0.18, 0.2), { color: COLORS.label, fontSize: '28px' });
}

makeSkip('decoder256', enc256b, dec256, 2.45, true, 0.9);
makeSkip('decoder128', enc128, dec128, 0.85, true, 0.75);
makeSkip('decoder64', enc64, dec64, -0.10, true, 0.45);
makeSkip('decoder32', enc32, dec32, -0.62, true, 0.20);
makeSkip('decoder16', enc16, dec16, -0.92, false, 0);

const timeY = -2.35;
makeLine([new THREE.Vector3(-7.95, timeY, 0.03), new THREE.Vector3(5.95, timeY, 0.03)], COLORS.time, 1);
const tCircle = new THREE.Mesh(
  new THREE.CircleGeometry(0.28, 48),
  new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide })
);
tCircle.position.set(-8.20, timeY, 0.04);
root.add(tCircle);
const tRing = new THREE.Mesh(
  new THREE.RingGeometry(0.28, 0.305, 48),
  new THREE.MeshBasicMaterial({ color: COLORS.time, side: THREE.DoubleSide })
);
tRing.position.copy(tCircle.position);
root.add(tRing);

const injectionArrows = [];
for (const r of pathRecords.slice(1, -1)) {
  const start = new THREE.Vector3(r.x - 0.55, timeY, 0.08);
  const end = new THREE.Vector3(r.x - 0.06, r.yBase - 0.02, 0.08);
  injectionArrows.push(makeArrow([start, end], COLORS.time, 0.055, 0.9));
}
for (let x = -7.4; x <= 5.4; x += 1.35) {
  makeArrow([new THREE.Vector3(x, timeY, 0.07), new THREE.Vector3(x + 0.38, timeY, 0.07)], COLORS.time, 0.045, 0.75);
}

const stripTiles = [];
for (let i = 0; i < 24; i++) {
  const tile = new THREE.Mesh(
    new THREE.PlaneGeometry(0.11, 0.08),
    new THREE.MeshBasicMaterial({ color: 0x9fc3d5, side: THREE.DoubleSide, transparent: true, opacity: 0.9 })
  );
  tile.position.set(-7.55 + i * 0.18, timeY + 0.15, 0.08);
  root.add(tile);
  stripTiles.push(tile);
}

function buildAttentionOverlay() {
  const group = new THREE.Group();
  group.position.set(-1.35, 1.05, 0.55);
  group.visible = false;

  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(2.45, 1.85),
    new THREE.MeshBasicMaterial({ color: 0xfffbf2, transparent: true, opacity: 0.96, side: THREE.DoubleSide })
  );
  group.add(panel);

  const borderPts = [
    [-1.225, -0.925], [1.225, -0.925], [1.225, 0.925], [-1.225, 0.925], [-1.225, -0.925]
  ].map(p => new THREE.Vector3(p[0], p[1], 0.01));
  group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(borderPts), new THREE.LineBasicMaterial({ color: 0x000000 })));

  const n = 16, gridSize = 1.18, cell = gridSize / n;
  const qx = 5, qy = 9;
  const queryPos = new THREE.Vector3(-0.78 + (qx + 0.5) * cell, -0.58 + (qy + 0.5) * cell, 0.035);
  for (let iy = 0; iy < n; iy++) {
    for (let ix = 0; ix < n; ix++) {
      const dx = ix - qx, dy = iy - qy;
      const weight = Math.exp(-(dx * dx + dy * dy) / 28) + 0.25 * Math.max(0, Math.sin(ix * 1.7 + iy * 0.9));
      const col = new THREE.Color().setHSL(0.08, 0.85, 0.25 + Math.min(0.48, weight * 0.25));
      const sq = new THREE.Mesh(
        new THREE.PlaneGeometry(cell * 0.88, cell * 0.88),
        new THREE.MeshBasicMaterial({ color: (ix === qx && iy === qy) ? 0xffe15a : col, side: THREE.DoubleSide, transparent: true, opacity: 0.92 })
      );
      sq.position.set(-0.78 + (ix + 0.5) * cell, -0.58 + (iy + 0.5) * cell, 0.03);
      group.add(sq);
    }
  }

  [[1, 2], [3, 13], [12, 4], [14, 11], [8, 8], [15, 15], [0, 14]].forEach(([ix, iy]) => {
    const p = new THREE.Vector3(-0.78 + (ix + 0.5) * cell, -0.58 + (iy + 0.5) * cell, 0.05);
    const ray = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([queryPos, p]),
      new THREE.LineBasicMaterial({ color: 0x4f6f80, transparent: true, opacity: 0.45 })
    );
    group.add(ray);
  });

  const miniA = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.38, 0.08), new THREE.MeshBasicMaterial({ color: 0x7f3d22 }));
  const miniB = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.38, 0.08), new THREE.MeshBasicMaterial({ color: 0x7f3d22 }));
  miniA.position.set(0.55, 0.26, 0.08);
  miniB.position.set(0.98, 0.26, 0.08);
  group.add(miniA, miniB);
