function makeLine(points, color = 0x000000, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const line = new THREE.Line(geom, mat);
  root.add(line);
  return line;
}

function makeArrow(points, color = 0x000000, size = 0.09, opacity = 1, parent = root) {
  const group = new THREE.Group();
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const line = new THREE.Line(geom, mat);
  group.add(line);

  const a = points[points.length - 2];
  const b = points[points.length - 1];
  const dir = new THREE.Vector3().subVectors(b, a).normalize();
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(size, size * 2.25, 18),
    new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity })
  );
  cone.position.copy(b);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.add(cone);
  parent.add(group);
  return group;
}

function setObjectOpacity(obj, opacity) {
  obj.traverse(o => {
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach(m => {
        m.transparent = opacity < 1;
        m.opacity = opacity;
        m.needsUpdate = true;
      });
    }
  });
}

function makeBoxVolume({ id, phase, x, h, w, depth, attention = false }) {
  const group = new THREE.Group();
  const yBase = -1.45;
  group.position.set(x, yBase + h / 2, -depth / 2);

  const sideMat = new THREE.MeshBasicMaterial({ color: attention ? 0xd58a67 : COLORS.side, transparent: true, opacity: 1 });
  const topMat = new THREE.MeshBasicMaterial({ color: 0xd98a64, transparent: true, opacity: 1 });
  const frontMat = new THREE.MeshBasicMaterial({ color: COLORS.front, transparent: true, opacity: 1 });
  const mats = [sideMat, sideMat, topMat, sideMat, frontMat, sideMat];

  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, depth), mats);
  group.add(mesh);

  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  group.add(edges);

  const activeEdges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry),
    new THREE.LineBasicMaterial({ color: COLORS.active })
  );
  activeEdges.scale.set(1.08, 1.04, 1.08);
  activeEdges.visible = false;
  group.add(activeEdges);

  root.add(group);

  const record = { id, phase, group, mesh, edges, activeEdges, x, h, w, depth, yBase, attention };
  blockRecords.push(record);
  if (phase) blockByPhase.set(phase, record);

  if (attention) {
    registerInteractive(group, {
      title: 'Self-attention residual block',
      tooltip: 'Click to expand 16×16 self-attention',
      body: 'At 16×16, each token can mix information from all 256 spatial positions rather than only nearby convolutional neighborhoods.',
      onClick: () => toggleAttentionOverlay(true)
    });
  }

  return record;
}

function noisyTexture(seedOffset = 0) {
  const W = 72, H = 72;
  const data = new Uint8Array(W * H * 4);
  let s = 123456 + seedOffset;
  function rand() {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  }
  for (let i = 0; i < W * H; i++) {
    const base = 120 + Math.floor(rand() * 90);
    data[i * 4 + 0] = Math.max(0, Math.min(255, base + (rand() - 0.5) * 70));
    data[i * 4 + 1] = Math.max(0, Math.min(255, base + (rand() - 0.5) * 65));
    data[i * 4 + 2] = Math.max(0, Math.min(255, base + (rand() - 0.5) * 85));
    data[i * 4 + 3] = 255;
  }
  const tex = new THREE.DataTexture(data, W, H, THREE.RGBAFormat);
  tex.needsUpdate = true;
  return tex;
}

function makePlaneFeature(id, x, output = false) {
  const h = 3.6, w = 0.86, yBase = -1.45;
  const group = new THREE.Group();
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({ map: noisyTexture(output ? 99 : 0), side: THREE.DoubleSide })
  );
  mesh.position.set(x, yBase + h / 2, 0.025);
  group.add(mesh);

  const pts = [
    new THREE.Vector3(x - w / 2, yBase, 0.035),
    new THREE.Vector3(x + w / 2, yBase, 0.035),
    new THREE.Vector3(x + w / 2, yBase + h, 0.035),
    new THREE.Vector3(x - w / 2, yBase + h, 0.035),
    new THREE.Vector3(x - w / 2, yBase, 0.035)
  ];
  const outline = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  group.add(outline);

  const activeEdges = outline.clone();
  activeEdges.material = new THREE.LineBasicMaterial({ color: COLORS.active });
  activeEdges.visible = false;
  group.add(activeEdges);

  root.add(group);
  const record = { id, phase: output ? 'output' : 'input', group, mesh, activeEdges, x, h, w, depth: 0.05, yBase };
  blockRecords.push(record);
  blockByPhase.set(record.phase, record);
  return record;
}

