    [-1.225, -0.925], [1.225, -0.925], [1.225, 0.925], [-1.225, 0.925], [-1.225, -0.925]
  ].map(p => new THREE.Vector3(p[0], p[1], 0.01));
  group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(borderPts), new THREE.LineBasicMaterial({ color: 0x000000 })));

  const n = 16, gridSize = 1.18, cell = gridSize / n;
  const qx = 5, qy = 9;
  const queryPos = new THREE.Vector3(-0.78 + (qx + 0.5) * cell, -0.58 + (qy + 0.5) * cell, 0.035);
  for (let iy = 0; iy < n; iy++) {
    for (let ix = 0; ix < n; ix++) {
      const dx = ix - qx, dy = iy - qy;
      const weight = Math.exp(-(dx * dx + dy * dy) / 28) + 0.25 * Math.max(0, Math.sin(ix * 1.7 + iy * 0.9));
      const col = new THREE.Color().setHSL(0.08, 0.85, 0.25 + Math.min(0.48, weight * 0.25));
      const sq = new THREE.Mesh(
        new THREE.PlaneGeometry(cell * 0.88, cell * 0.88),
        new THREE.MeshBasicMaterial({ color: (ix === qx && iy === qy) ? 0xffe15a : col, side: THREE.DoubleSide, transparent: true, opacity: 0.92 })
      );
      sq.position.set(-0.78 + (ix + 0.5) * cell, -0.58 + (iy + 0.5) * cell, 0.03);
      group.add(sq);
    }
  }

  [[1, 2], [3, 13], [12, 4], [14, 11], [8, 8], [15, 15], [0, 14]].forEach(([ix, iy]) => {
    const p = new THREE.Vector3(-0.78 + (ix + 0.5) * cell, -0.58 + (iy + 0.5) * cell, 0.05);
    const ray = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([queryPos, p]),
      new THREE.LineBasicMaterial({ color: 0x4f6f80, transparent: true, opacity: 0.45 })
    );
    group.add(ray);
  });

  const miniA = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.38, 0.08), new THREE.MeshBasicMaterial({ color: 0x7f3d22 }));
  const miniB = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.38, 0.08), new THREE.MeshBasicMaterial({ color: 0x7f3d22 }));
  miniA.position.set(0.55, 0.26, 0.08);
