  group.add(new THREE.LineSegments(new THREE.EdgesGeometry(miniA.geometry), new THREE.LineBasicMaterial({ color: 0x000000 })).translateX(0.55).translateY(0.26).translateZ(0.08));
  group.add(new THREE.LineSegments(new THREE.EdgesGeometry(miniB.geometry), new THREE.LineBasicMaterial({ color: 0x000000 })).translateX(0.98).translateY(0.26).translateZ(0.08));
  makeArrow([new THREE.Vector3(0.70, 0.26, 0.18), new THREE.Vector3(0.84, 0.26, 0.18)], 0x222222, 0.035, 0.9, group);

  const localPatch = new THREE.Mesh(
    new THREE.PlaneGeometry(0.55, 0.22),
