  blockRecords.forEach(r => {
    const active = r.phase === phase || (phase === 'encoder256' && r.id === 'enc256b') || (phase === 'decoder256' && r.id === 'outBlock');
    setObjectOpacity(r.group, active ? 1 : 0.42);
    if (r.activeEdges) r.activeEdges.visible = active;
  });
  skipRecords.forEach(s => {
    const active = s.phase === phase;
    s.arrow.traverse(o => {
      if (o.material) {
        o.material.color.setHex(active ? COLORS.active : COLORS.skip);
        o.material.opacity = active ? 1 : 0.62;
        o.material.transparent = true;
      }
    });
  });
  if (phase === 'encoder16') toggleAttentionOverlay(true);
}

function setTimestep(t) {
  t = Math.max(0, Math.min(1000, Number(t) || 0));
  document.getElementById('timestepSlider').value = t;
  document.getElementById('tValue').textContent = String(Math.round(t));
  tNumLabel.div.innerHTML = 't = ' + Math.round(t);

  const hueBase = 0.54 + 0.18 * (t / 1000);
  stripTiles.forEach((tile, i) => {
    const v = 0.5 + 0.5 * Math.sin(i * 0.85 + t * 0.025);
    tile.material.color.setHSL(hueBase, 0.55 + 0.25 * v, 0.35 + 0.35 * v);
  });
  injectionArrows.forEach((a, i) => {
    const v = 0.45 + 0.45 * Math.sin(t * 0.035 + i * 0.7);
    a.traverse(o => {
      if (o.material) {
        o.material.opacity = 0.42 + 0.55 * v;
        o.material.transparent = true;
      }
    });
  });
}

function goToStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  const step = demoSteps[currentStep];
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarration').textContent = step.narration;
  setPhase(step.state.networkPhase);
  setTimestep(step.state.timestep);
}
window.goToStep = goToStep;

document.getElementById('phaseBtn').addEventListener('click', () => {
  const idx = phases.indexOf(currentPhase);
  setPhase(phases[(idx + 1) % phases.length]);
});
document.getElementById('timestepSlider').addEventListener('input', (e) => setTimestep(e.target.value));
document.getElementById('demoPrev').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('demoNext').addEventListener('click', () => goToStep(currentStep + 1));

let pulseClock = 0;
function updateFigurePulse() {
  requestAnimationFrame(updateFigurePulse);
  pulseClock += 0.035;
  skipRecords.forEach(s => {
    if (s.phase !== currentPhase) return;
    const scale = 1 + 0.18 * Math.sin(pulseClock * 4);
    s.arrow.children.forEach(child => {
      if (child.isMesh) child.scale.setScalar(scale);
    });
  });
}
updateFigurePulse();

goToStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

