function setGroupOpacity(obj, opacity) {
  obj.traverse(o => {
    if (!o.material) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    mats.forEach(m => {
      m.transparent = opacity < 1;
      m.opacity = opacity;
      m.needsUpdate = true;
    });
  });
}

function roundedRectShape(w, h, r) {
  const x = -w / 2, y = -h / 2;
  const s = new THREE.Shape();
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

function makeLegend() {
  const g = new THREE.Group();
  g.position.set(-7.65, 2.35, 0.22);

  const w = 2.12, h = 1.34;
  const fill = new THREE.Mesh(
    new THREE.ShapeGeometry(roundedRectShape(w, h, 0.18)),
    new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide })
  );
  g.add(fill);

  const borderPts = [];
  const n = 12;
  const r = 0.18;
  const x0 = -w / 2, x1 = w / 2, y0 = -h / 2, y1 = h / 2;
  function addArc(cx, cy, a0, a1) {
    for (let i = 0; i <= n; i++) {
      const a = a0 + (a1 - a0) * i / n;
      borderPts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), 0.012));
    }
  }
  borderPts.push(new THREE.Vector3(x0 + r, y0, 0.012), new THREE.Vector3(x1 - r, y0, 0.012));
  addArc(x1 - r, y0 + r, -Math.PI / 2, 0);
  borderPts.push(new THREE.Vector3(x1, y1 - r, 0.012));
  addArc(x1 - r, y1 - r, 0, Math.PI / 2);
  borderPts.push(new THREE.Vector3(x0 + r, y1, 0.012));
  addArc(x0 + r, y1 - r, Math.PI / 2, Math.PI);
  borderPts.push(new THREE.Vector3(x0, y0 + r, 0.012));
  addArc(x0 + r, y0 + r, Math.PI, 1.5 * Math.PI);
  borderPts.push(new THREE.Vector3(x0 + r, y0, 0.012));
  g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(borderPts), new THREE.LineBasicMaterial({ color: 0x000000 })));

  arrowObject([new THREE.Vector3(-0.18, 0.42, 0.03), new THREE.Vector3(0.35, 0.42, 0.03)], 0x222222, 0.045, 1, g);
  arrowObject([new THREE.Vector3(-0.18, -0.05, 0.03), new THREE.Vector3(0.35, -0.05, 0.03)], COLORS.attn, 0.045, 1, g);

  root.add(g);
  return g;
}

