function makeNoiseTexture(seedOffset) {
  const W = 80, H = 80;
  const data = new Uint8Array(W * H * 4);
  let s = 24681357 + seedOffset;
  function rnd() {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  }
  for (let i = 0; i < W * H; i++) {
    const vignette = 0.8 + 0.2 * Math.sin(i * 0.073);
    const base = Math.floor((115 + rnd() * 105) * vignette);
    data[i * 4] = Math.max(0, Math.min(255, base + (rnd() - 0.5) * 70));
    data[i * 4 + 1] = Math.max(0, Math.min(255, base + (rnd() - 0.5) * 65));
    data[i * 4 + 2] = Math.max(0, Math.min(255, base + (rnd() - 0.5) * 85));
    data[i * 4 + 3] = 255;
  }
  const tex = new THREE.DataTexture(data, W, H, THREE.RGBAFormat);
  tex.needsUpdate = true;
  return tex;
}

