  const outline = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x000000 }));
  g.add(outline);

  const active = outline.clone();
  active.material = new THREE.LineBasicMaterial({ color: COLORS.active });
  active.scale.set(1.04, 1.02, 1);
  active.visible = false;
  g.add(active);

  root.add(g);
  const rec = { id, phase, group: g, x, yBase, h, w, depth: 0.03, activeEdges: active, attention: false };
  blocks.push(rec);
  blockByPhase.set(phase, rec);
  return rec;
}

function makeVolume({ id, phase, x, h, w, depth, attention = false }) {
  const yBase = -1.35;
  const g = new THREE.Group();
  g.position.set(x, yBase + h / 2, -depth / 2);

  const mats = [
    makeMaterial(COLORS.side), makeMaterial(COLORS.side),
    makeMaterial(COLORS.top), makeMaterial(COLORS.side),
    makeMaterial(COLORS.front), makeMaterial(COLORS.front)
  ];
  const geom = new THREE.BoxGeometry(w, h, depth);
  const mesh = new THREE.Mesh(geom, mats);
  g.add(mesh);

  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geom), new THREE.LineBasicMaterial({ color: 0x000000 }));
  g.add(edges);

  const activeEdges = new THREE.LineSegments(new THREE.EdgesGeometry(geom), new THREE.LineBasicMaterial({ color: COLORS.active }));
  activeEdges.scale.set(1.08, 1.04, 1.10);
  activeEdges.visible = false;
  g.add(activeEdges);

  let attnHalo = null;
  if (attention) {
    attnHalo = new THREE.LineSegments(new THREE.EdgesGeometry(geom), new THREE.LineBasicMaterial({ color: COLORS.attn, transparent: true, opacity: 0.42 }));
    attnHalo.scale.set(1.045, 1.025, 1.06);
    g.add(attnHalo);
  }

  root.add(g);
  const rec = { id, phase, group: g, mesh, activeEdges, attnHalo, x, yBase, h, w, depth, attention };
  blocks.push(rec);
  if (phase) blockByPhase.set(phase, rec);

  if (attention) {
    registerInteractive(g, {
      title: 'Res. block + self-attention',
      tooltip: 'Click to expand 16×16 self-attention',
      body: 'At small spatial scales, every token can attend to all other positions, giving the U-Net global context while keeping computation manageable.',
      onClick: () => toggleAttentionOverlay(true)
    });
  }
  return rec;
}

const inputPlane = makePlaneFeature('input', 'input', -7.05, false);
const enc256a = makeVolume({ id: 'enc256a', phase: 'encoder256', x: -6.38, h: 3.6, w: 0.25, depth: 0.62 });
const enc256b = makeVolume({ id: 'enc256b', phase: null, x: -5.88, h: 3.6, w: 0.34, depth: 0.68 });
