const dec64 = makeVolume({ id: 'dec64', phase: 'decoder64', x: 3.72, h: 0.9, w: 0.52, depth: 0.54 });
const dec128 = makeVolume({ id: 'dec128', phase: 'decoder128', x: 4.42, h: 1.8, w: 0.40, depth: 0.62 });
const dec256 = makeVolume({ id: 'dec256', phase: 'decoder256', x: 5.12, h: 3.6, w: 0.34, depth: 0.68 });
