const path = [inputPlane, enc256a, enc256b, enc128, enc64, enc32, enc16, bottleneck, dec8, dec16, dec32, dec64, dec128, dec256, outBlock, outputPlane];

for (let i = 0; i < path.length - 1; i++) {
