function buildAttentionOverlay() {
  const g = new THREE.Group();
  g.position.set(-1.25, 0.95, 0.70);
  g.visible = false;

  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(2.35, 1.72),
    new THREE.MeshBasicMaterial({ color: 0xfffbf2, transparent: true, opacity: 0.97, side: THREE.DoubleSide })
  );
  g.add(panel);
  const border = [
    [-1.175, -0.86], [1.175, -0.86], [1.175, 0.86], [-1.175, 0.86], [-1.175, -0.86]
  ].map(([x, y]) => new THREE.Vector3(x, y, 0.02));
  g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(border), new THREE.LineBasicMaterial({ color: 0x000000 })));

  const n = 16;
  const grid = 1.12;
  const cell = grid / n;
  const originX = -0.92;
  const originY = -0.58;
  const qx = 5, qy = 10;
  const query = new THREE.Vector3(originX + (qx + 0.5) * cell, originY + (qy + 0.5) * cell, 0.05);

  for (let iy = 0; iy < n; iy++) {
    for (let ix = 0; ix < n; ix++) {
      const dx = ix - qx, dy = iy - qy;
      const w = Math.exp(-(dx * dx + dy * dy) / 30) + 0.15 * (1 + Math.sin(ix * 1.9 + iy * 0.7));
      const c = new THREE.Color().setHSL(0.08, 0.82, 0.24 + Math.min(0.48, w * 0.22));
      const sq = new THREE.Mesh(
        new THREE.PlaneGeometry(cell * 0.86, cell * 0.86),
        new THREE.MeshBasicMaterial({
          color: (ix === qx && iy === qy) ? 0xffe15a : c,
          transparent: true,
          opacity: 0.94,
          side: THREE.DoubleSide
        })
      );
      sq.position.set(originX + (ix + 0.5) * cell, originY + (iy + 0.5) * cell, 0.04);
      g.add(sq);
    }
  }

  [[1, 2], [3, 14], [9, 7], [12, 3], [15, 12], [0, 15], [14, 6]].forEach(([ix, iy]) => {
    const p = new THREE.Vector3(originX + (ix + 0.5) * cell, originY + (iy + 0.5) * cell, 0.06);
    g.add(new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([query, p]),
      new THREE.LineBasicMaterial({ color: COLORS.time, transparent: true, opacity: 0.42 })
    ));
  });

  const mini1 = new THREE.Mesh(new THREE.BoxGeometry(0.30, 0.34, 0.08), makeMaterial(COLORS.front));
  const mini2 = new THREE.Mesh(new THREE.BoxGeometry(0.30, 0.34, 0.08), makeMaterial(COLORS.front));
  mini1.position.set(0.55, 0.25, 0.08);
  mini2.position.set(0.98, 0.25, 0.08);
  g.add(mini1, mini2);
  const e1 = new THREE.LineSegments(new THREE.EdgesGeometry(mini1.geometry), new THREE.LineBasicMaterial({ color: 0x000000 }));
  e1.position.copy(mini1.position);
  const e2 = new THREE.LineSegments(new THREE.EdgesGeometry(mini2.geometry), new THREE.LineBasicMaterial({ color: 0x000000 }));
  e2.position.copy(mini2.position);
  g.add(e1, e2);
