}

const attentionOverlay = buildAttentionOverlay();

function toggleAttentionOverlay(open) {
  overlayOpen = open == null ? !overlayOpen : !!open;
  attentionOverlay.visible = overlayOpen;
}

const phases = [
  'input', 'encoder256', 'encoder128', 'encoder64', 'encoder32', 'encoder16',
  'bottleneck8', 'decoder16', 'decoder32', 'decoder64', 'decoder128', 'decoder256', 'output'
];

function setPhase(phase, highlight = true) {
  phaseHighlightOn = highlight;
  currentPhase = phase;
  document.getElementById('phaseBtn').textContent = 'Step: ' + phase;

  blocks.forEach(r => {
    const active =
      r.phase === phase ||
      (phase === 'encoder256' && r.id === 'enc256b') ||
      (phase === 'decoder256' && r.id === 'outBlock');
    if (r.activeEdges) r.activeEdges.visible = active;
    setGroupOpacity(r.group, !phaseHighlightOn ? 1 : (active ? 1 : 0.78));
  });

  skipRecords.forEach(s => {
    const active = s.phase === phase;
    s.arrow.traverse(o => {
      if (!o.material) return;
      o.material.color.setHex(active ? COLORS.active : COLORS.skip);
      o.material.opacity = !phaseHighlightOn ? 1 : (active ? 1 : 0.76);
      o.material.transparent = o.material.opacity < 1;
    });
  });

  if (phase === 'encoder16' || phase === 'decoder16' || phase === 'bottleneck8') toggleAttentionOverlay(true);
}

function setTimestep(t) {
  t = Math.max(0, Math.min(1000, Number(t) || 0));
  document.getElementById('timestepSlider').value = t;
  document.getElementById('tValue').textContent = String(Math.round(t));
  tNumLabel.div.innerHTML = 't = ' + Math.round(t);

  const hueBase = 0.53 + 0.16 * (t / 1000);
  stripTiles.forEach((tile, i) => {
    const v = 0.5 + 0.5 * Math.sin(i * 0.82 + t * 0.025);
    tile.material.color.setHSL(hueBase, 0.52 + 0.24 * v, 0.34 + 0.33 * v);
  });

  injectionArrows.forEach((a, i) => {
    const v = 0.5 + 0.5 * Math.sin(t * 0.03 + i * 0.63);
    a.traverse(o => {
      if (!o.material) return;
      o.material.opacity = 0.55 + 0.40 * v;
      o.material.transparent = true;
    });
  });
}

const demoSteps = [
  { title: 'Input feature map', narration: 'The noisy image enters the U-Net as a 256×256×3 feature plane. The timestep t is already embedded and ready to condition every residual block.', state: { networkPhase: 'input', timestep: 500 } },
  { title: 'Encoder at 256×256', narration: 'The first encoder blocks lift the image into 128 channels while preserving the full 256×256 spatial grid. The time embedding arrow into this block shows that denoising behavior depends on t.', state: { networkPhase: 'encoder256', timestep: 500 } },
  { title: 'Downsample to 128×128', narration: 'The encoder halves the spatial size and keeps a feature volume at 128×128×128. Highlighting the transition makes the downsampling step visible.', state: { networkPhase: 'encoder128', timestep: 500 } },
  { title: 'Downsample to 64×64', narration: 'At 64×64, the model uses more channels, here 256, to represent higher-level structure while the spatial grid becomes smaller.', state: { networkPhase: 'encoder64', timestep: 500 } },
  { title: 'Downsample to 32×32', narration: 'The encoder continues compressing spatial information. This intermediate representation will later be concatenated back into the decoder at the matching scale.', state: { networkPhase: 'encoder32', timestep: 500 } },
  { title: 'Attention-scale features', narration: 'At 16×16×512 the grid is small enough that self-attention across all positions is practical. Clicking this block opens the attention overlay.', state: { networkPhase: 'encoder16', timestep: 500 } },
  { title: 'Bottleneck at 8×8', narration: 'The bottleneck is the most compressed representation, shown as an 8×8×512 volume. It carries global context before the decoder begins expanding resolution.', state: { networkPhase: 'bottleneck8', timestep: 500 } },
  { title: 'Decoder begins upsampling', narration: 'The decoder restores spatial resolution. When it reaches a matching encoder scale, the corresponding Concatenate skip connection pulses to show that encoder features are reused.', state: { networkPhase: 'decoder16', timestep: 500 } },
  { title: 'Decoder at 32×32', narration: 'The 32×32 skip connection provides fine encoder features that were saved before further downsampling. Concatenation helps preserve spatial detail.', state: { networkPhase: 'decoder32', timestep: 500 } },
  { title: 'Decoder at 64×64', narration: 'Another skip connection joins same-resolution encoder and decoder features. The decoder combines global bottleneck context with local features from the encoder path.', state: { networkPhase: 'decoder64', timestep: 500 } },
  { title: 'Decoder at 128×128', narration: 'As resolution increases, the feature volume becomes spatially larger again. The time embedding still conditions every residual block in the decoder.', state: { networkPhase: 'decoder128', timestep: 500 } },
  { title: 'Decoder at 256×256', narration: 'The final high-resolution decoder blocks recover the original spatial size. The top skip connection supplies high-resolution encoder features for precise output structure.', state: { networkPhase: 'decoder256', timestep: 500 } },
  { title: 'Predicted denoising output', narration: 'The U-Net returns a full-resolution output plane, typically interpreted as the predicted noise or denoised update for the diffusion step.', state: { networkPhase: 'output', timestep: 500 } }
];

function goToStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  const step = demoSteps[currentStep];
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarration').textContent = step.narration;
  setPhase(step.state.networkPhase, true);
  setTimestep(step.state.timestep);
}
window.goToStep = goToStep;

document.getElementById('phaseBtn').addEventListener('click', () => {
  const idx = phases.indexOf(currentPhase);
  setPhase(phases[(idx + 1) % phases.length], true);
});
document.getElementById('timestepSlider').addEventListener('input', e => setTimestep(e.target.value));
document.getElementById('demoPrev').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('demoNext').addEventListener('click', () => goToStep(currentStep + 1));

const closeRay = new THREE.Raycaster();
const closePointer = new THREE.Vector2();
canvas.addEventListener('click', event => {
  const rect = canvas.getBoundingClientRect();
  closePointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  closePointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  closeRay.setFromCamera(closePointer, camera);
  const hits = closeRay.intersectObjects([enc16.group, bottleneck.group, dec16.group, attentionOverlay], true);
  if (!hits.length && overlayOpen) toggleAttentionOverlay(false);
});

function pulseLoop() {
  requestAnimationFrame(pulseLoop);
  pulseClock += 0.035;
  skipRecords.forEach(s => {
    const active = phaseHighlightOn && s.phase === currentPhase;
    s.arrow.traverse(o => {
      if (!o.material) return;
      if (active) {
        o.material.color.setHex((Math.sin(pulseClock * 5) > 0) ? COLORS.active : COLORS.skip);
      }
    });
    s.arrow.children.forEach(child => {
      if (child.isMesh) {
        const sc = active ? 1 + 0.16 * Math.max(0, Math.sin(pulseClock * 5)) : 1;
        child.scale.setScalar(sc);
      }
    });
  });
}
pulseLoop();

setPhase('input', false);
setTimestep(500);
