});

function goToStep(i) {
  const target = demoSteps[i];
  if (!target) return;

  state.activeStep = i;
  state.tween = {
    startTime: performance.now(),
    duration: 1000,
    fromRotation: state.rotationCamera2,
    fromTranslation: state.translationCamera2,
    toRotation: target.rotationCamera2,
    toTranslation: target.translationCamera2
  };

  function tick(now) {
    if (!state.tween) return;
    const t = Math.min((now - state.tween.startTime) / state.tween.duration, 1);
    const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    state.rotationCamera2 = THREE.MathUtils.lerp(state.tween.fromRotation, state.tween.toRotation, eased);
    state.translationCamera2 = THREE.MathUtils.lerp(state.tween.fromTranslation, state.tween.toTranslation, eased);
    updateScene();

    if (t < 1) {
      requestAnimationFrame(tick);
    } else {
      state.rotationCamera2 = state.tween.toRotation;
      state.translationCamera2 = state.tween.toTranslation;
      state.tween = null;
      updateScene();
    }
  }

  requestAnimationFrame(tick);
}

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
