<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// rounded-corner legend box → ShapeGeometry rounded rectangle white fill + black Line border
// legend black right-pointing arrow labeled 'Res. block' → Line + ConeGeometry arrowhead
// legend pale blue right-pointing arrow labeled 'Res. block + self-attention' → Line + ConeGeometry arrowhead
// left input image feature plane with noisy texture → PlaneGeometry + DataTexture + black Line outline
// encoder/decoder feature map volumes → BoxGeometry thin cuboids with dark-brown front, copper sides, black EdgesGeometry
// self-attention-capable volumes → BoxGeometry cuboids with subtle pale-blue halo and click registration
// main flow arrows between neighboring volumes → black Line segments + ConeGeometry arrowheads
// skip connections → salmon Line polylines + ConeGeometry arrowheads
// timestep node → CircleGeometry disk + RingGeometry outline + addLabel "t"
// time embedding baseline and injection arrows → blue-gray Lines + ConeGeometry arrowheads with timestep color pulse
// bottom embedding flow arrows → short blue-gray right-pointing Lines + ConeGeometry arrowheads
// click-expanded self-attention overlay → hidden Group with panel PlaneGeometry, 16×16 heatmap cells, attention rays, highlighted query, mini residual block diagram

const COLORS = {
  front: 0x7f3d22,
  side: 0xcf7d59,
  top: 0xd78b64,
  skip: 0xd57d5c,
  time: 0x4f6f80,
  attn: 0x9fc3d5,
  label: '#854126',
  active: 0xffd34d
};

const root = new THREE.Group();
scene.add(root);

const blocks = [];
const blockByPhase = new Map();
const skipRecords = [];
const injectionArrows = [];
const mainFlowArrows = [];
let currentPhase = 'input';
let currentStep = 0;
let phaseHighlightOn = false;
let overlayOpen = false;
let pulseClock = 0;

function mat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide
  });
}

function lineObject(points, color, opacity = 1, parent = root) {
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(points),
    new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity })
  );
  parent.add(line);
  return line;
}

function arrowObject(points, color, size = 0.055, opacity = 1, parent = root) {
  const g = new THREE.Group();
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(points),
    new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity })
  );
  g.add(line);
  const a = points[points.length - 2];
  const b = points[points.length - 1];
  const dir = new THREE.Vector3().subVectors(b, a).normalize();
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(size, size * 2.35, 18),
    new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity })
  );
  cone.position.copy(b);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  g.add(cone);
  parent.add(g);
  return g;
}

function setGroupOpacity(obj, opacity) {
  obj.traverse(o => {
    if (!o.material) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    mats.forEach(m => {
      m.transparent = opacity < 1;
      m.opacity = opacity;
      m.needsUpdate = true;
    });
  });
}

function roundedRectShape(w, h, r) {
  const x = -w / 2, y = -h / 2;
  const s = new THREE.Shape();
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

function makeLegend() {
  const g = new THREE.Group();
  g.position.set(-7.50, 2.55, 0.18);

  const w = 2.05, h = 1.28;
  const fill = new THREE.Mesh(
    new THREE.ShapeGeometry(roundedRectShape(w, h, 0.18)),
    mat(0xffffff, 1)
  );
  g.add(fill);

  const pts = [];
  const r = 0.18, x0 = -w / 2, x1 = w / 2, y0 = -h / 2, y1 = h / 2;
  function arc(cx, cy, a0, a1) {
    for (let i = 0; i <= 10; i++) {
      const a = a0 + (a1 - a0) * i / 10;
      pts.push(new THREE.Vector3(cx + r * Math.cos(a), cy + r * Math.sin(a), 0.015));
    }
  }
  pts.push(new THREE.Vector3(x0 + r, y0, 0.015), new THREE.Vector3(x1 - r, y0, 0.015));
  arc(x1 - r, y0 + r, -Math.PI / 2, 0);
  pts.push(new THREE.Vector3(x1, y1 - r, 0.015));
  arc(x1 - r, y1 - r, 0, Math.PI / 2);
  pts.push(new THREE.Vector3(x0 + r, y1, 0.015));
  arc(x0 + r, y1 - r, Math.PI / 2, Math.PI);
  pts.push(new THREE.Vector3(x0, y0 + r, 0.015));
  arc(x0 + r, y0 + r, Math.PI, Math.PI * 1.5);
  pts.push(new THREE.Vector3(x0 + r, y0, 0.015));
  g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color: 0x000000 })));

  arrowObject([new THREE.Vector3(-0.15, 0.42, 0.035), new THREE.Vector3(0.34, 0.42, 0.035)], 0x333a3d, 0.04, 1, g);
  arrowObject([new THREE.Vector3(-0.15, -0.05, 0.035), new THREE.Vector3(0.34, -0.05, 0.035)], COLORS.attn, 0.04, 1, g);
  root.add(g);
}

makeLegend();

function makeNoiseTexture(seedOffset) {
  const W = 96, H = 96;
  const data = new Uint8Array(W * H * 4);
  let s = 1357911 + seedOffset;
  function rnd() {
    s = (1664525 * s + 1013904223) >>> 0;
    return s / 4294967296;
  }
  for (let i = 0; i < W * H; i++) {
    const band = 0.5 + 0.5 * Math.sin((i % W) * 0.11 + Math.floor(i / W) * 0.07);
    const n = rnd();
    const base = 112 + 102 * n;
    data[i * 4] = Math.max(0, Math.min(255, base + 32 * (rnd() - 0.5) + 18 * band));
    data[i * 4 + 1] = Math.max(0, Math.min(255, base + 38 * (rnd() - 0.5)));
    data[i * 4 + 2] = Math.max(0, Math.min(255, base + 46 * (rnd() - 0.5) + 10 * (1 - band)));
    data[i * 4 + 3] = 255;
  }
  const tex = new THREE.DataTexture(data, W, H, THREE.RGBAFormat);
  tex.needsUpdate = true;
  return tex;
}

function makePlaneFeature(id, phase, x, output = false) {
  const h = 3.6, w = 0.22, yBase = -1.25;
  const g = new THREE.Group();
  g.position.set(x, yBase + h / 2, 0);

  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({ map: makeNoiseTexture(output ? 701 : 0), side: THREE.DoubleSide })
  );
  mesh.position.set(0, 0, 0.025);
  g.add(mesh);

  const local = [
    new THREE.Vector3(-w / 2, -h / 2, 0.045),
    new THREE.Vector3(w / 2, -h / 2, 0.045),
    new THREE.Vector3(w / 2, h / 2, 0.045),
    new THREE.Vector3(-w / 2, h / 2, 0.045),
    new THREE.Vector3(-w / 2, -h / 2, 0.045)
  ];
  const outline = new THREE.Line(new THREE.BufferGeometry().setFromPoints(local), new THREE.LineBasicMaterial({ color: 0x000000 }));
  g.add(outline);

  const activeEdges = new THREE.Line(new THREE.BufferGeometry().setFromPoints(local), new THREE.LineBasicMaterial({ color: COLORS.active }));
  activeEdges.scale.set(1.08, 1.03, 1);
  activeEdges.visible = false;
  g.add(activeEdges);

  root.add(g);
  const rec = { id, phase, group: g, x, yBase, h, w, depth: 0.02, activeEdges, attention: false, isPlane: true };
  blocks.push(rec);
  blockByPhase.set(phase, rec);
  return rec;
}

function makeVolume({ id, phase, x, h, w, depth = 0.52, attention = false }) {
  const yBase = -1.25;
  const g = new THREE.Group();
  g.position.set(x, yBase + h / 2, -depth / 2);

  const geom = new THREE.BoxGeometry(w, h, depth);
  const mesh = new THREE.Mesh(geom, [
    mat(COLORS.side), mat(COLORS.side),
    mat(COLORS.top), mat(COLORS.side),
    mat(COLORS.front), mat(COLORS.front)
  ]);
  g.add(mesh);

  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geom), new THREE.LineBasicMaterial({ color: 0x000000 }));
  g.add(edges);

  const activeEdges = new THREE.LineSegments(new THREE.EdgesGeometry(geom), new THREE.LineBasicMaterial({ color: COLORS.active }));
  activeEdges.scale.set(1.08, 1.045, 1.08);
  activeEdges.visible = false;
  g.add(activeEdges);

  if (attention) {
    const halo = new THREE.LineSegments(
      new THREE.EdgesGeometry(geom),
      new THREE.LineBasicMaterial({ color: COLORS.attn, transparent: true, opacity: 0.44 })
    );
    halo.scale.set(1.045, 1.025, 1.05);
    g.add(halo);
  }

  root.add(g);
  const rec = { id, phase, group: g, mesh, activeEdges, x, yBase, h, w, depth, attention };
  blocks.push(rec);
  if (phase) blockByPhase.set(phase, rec);

  if (attention) {
    registerInteractive(g, {
      title: 'Res. block + self-attention',
      tooltip: 'Click to inspect 16×16 self-attention',
      body: 'At the small 16×16 and 8×8 feature grids, a token can mix information from all other spatial positions. This gives the denoiser global context while preserving the U-Net skip structure.',
      onClick: () => toggleAttentionOverlay(true)
    });
  }
  return rec;
}

