function buildAttentionOverlay() {
  const g = new THREE.Group();
  g.position.set(-1.18, 0.98, 0.72);
  g.visible = false;

  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(2.25, 1.60),
    mat(0xfffbf2, 0.97)
  );
  g.add(panel);
  const border = [
    [-1.125, -0.80], [1.125, -0.80], [1.125, 0.80], [-1.125, 0.80], [-1.125, -0.80]
  ].map(([x, y]) => new THREE.Vector3(x, y, 0.025));
  g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(border), new THREE.LineBasicMaterial({ color: 0x000000 })));

  const n = 16;
  const grid = 1.04;
  const cell = grid / n;
  const originX = -0.92;
  const originY = -0.56;
  const qx = 5, qy = 10;
  const query = new THREE.Vector3(originX + (qx + 0.5) * cell, originY + (qy + 0.5) * cell, 0.07);

  for (let iy = 0; iy < n; iy++) {
    for (let ix = 0; ix < n; ix++) {
      const dx = ix - qx, dy = iy - qy;
      const weight = Math.exp(-(dx * dx + dy * dy) / 31) + 0.12 * (1 + Math.sin(ix * 1.7 + iy * 0.9));
      const c = new THREE.Color().setHSL(0.07, 0.82, 0.24 + Math.min(0.48, weight * 0.22));
      const sq = new THREE.Mesh(
        new THREE.PlaneGeometry(cell * 0.86, cell * 0.86),
        mat((ix === qx && iy === qy) ? 0xffe15a : c.getHex(), 0.94)
      );
      sq.position.set(originX + (ix + 0.5) * cell, originY + (iy + 0.5) * cell, 0.045);
      g.add(sq);
    }
  }

  [[1, 2], [3, 14], [9, 7], [12, 3], [15, 12], [0, 15], [14, 6], [7, 1]].forEach(([ix, iy]) => {
    const p = new THREE.Vector3(originX + (ix + 0.5) * cell, originY + (iy + 0.5) * cell, 0.065);
    g.add(new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([query, p]),
      new THREE.LineBasicMaterial({ color: COLORS.time, transparent: true, opacity: 0.38 })
    ));
  });

  const mini1 = new THREE.Mesh(new THREE.BoxGeometry(0.29, 0.34, 0.08), mat(COLORS.front));
  const mini2 = new THREE.Mesh(new THREE.BoxGeometry(0.29, 0.34, 0.08), mat(COLORS.front));
  mini1.position.set(0.50, 0.23, 0.08);
  mini2.position.set(0.91, 0.23, 0.08);
  g.add(mini1, mini2);
  [mini1, mini2].forEach(m => {
    const e = new THREE.LineSegments(new THREE.EdgesGeometry(m.geometry), new THREE.LineBasicMaterial({ color: 0x000000 }));
    e.position.copy(m.position);
    g.add(e);
  });
  arrowObject([new THREE.Vector3(0.65, 0.23, 0.15), new THREE.Vector3(0.76, 0.23, 0.15)], 0x222222, 0.023, 1, g);

  const localPatch = new THREE.Mesh(new THREE.PlaneGeometry(0.62, 0.24), mat(0xdde7ec, 0.92));
  localPatch.position.set(0.72, -0.39, 0.05);
  g.add(localPatch);

  root.add(g);
  return g;
}

